mapper.select:
select
proprietor.*
from proprietor proprietor

    and proprietor.id = #{id}
    and proprietor.name like concat('%',#{name},'%')
    and proprietor.tel like concat('%',#{tel},'%')
    and proprietor.house_info = #{houseInfo}
    and proprietor.car_number = #{carNumber}
    and proprietor.avatar = #{avatar}
    and proprietor.username = #{username}
    and proprietor.password = #{password}
    and proprietor.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from proprietor proprietor

    and proprietor.id = #{id}
    and proprietor.name like concat('%',#{name},'%')
    and proprietor.tel like concat('%',#{tel},'%')
    and proprietor.house_info = #{houseInfo}
    and proprietor.car_number = #{carNumber}
    and proprietor.avatar = #{avatar}
    and proprietor.username = #{username}
    and proprietor.password = #{password}
    and proprietor.create_time = #{createTime}
